def recover_plan(state):
    result={"run":[],"reconcile":[],"skipped":[]}
    for job in state["jobs"]:
        periods=sorted(set(job["due"]))
        statuses=job.get("status",{})
        policy=job["policy"]
        if policy not in {"backfill","latest_only"}:
            raise ValueError("unsupported recovery policy")
        selected=periods if policy=="backfill" else periods[-1:]
        for period in periods:
            status=statuses.get(period,"missing")
            key=job["name"]+":"+period
            if status=="complete":
                result["skipped"].append({"key":key,"reason":"complete"})
            elif status=="unknown":
                result["reconcile"].append({"key":key,"reason":"unknown_result"})
            elif period in selected:
                result["run"].append({"key":key,"job":job["name"],"period":period})
            else:
                result["skipped"].append({"key":key,"reason":"superseded_by_latest"})
    result["run"].sort(key=lambda row:(row["period"],row["job"]))
    result["reconcile"].sort(key=lambda row:row["key"])
    result["skipped"].sort(key=lambda row:row["key"])
    return result
```

